 ['the chessboard of the chapter: a dictionary of squares, printed with star syntax', 'BOARD_TEMPLATE = """\n    a    b    c    d    e    f    g    h\n   ____ ____ ____ ____ ____ ____ ____ ____\n  ||||||    ||||||    ||||||    ||||||    |\n8 ||{}|| {} ||{}|| {} ||{}|| {} ||{}|| {} |\n  ||||||____||||||____||||||____||||||____|\n  |    ||||||    ||||||    ||||||    ||||||\n7 | {} ||{}|| {} ||{}|| {} ||{}|| {} ||{}||\n  |____||||||____||||||____||||||____||||||\n  ||||||    ||||||    ||||||    ||||||    |\n6 ||{}|| {} ||{}|| {} ||{}|| {} ||{}|| {} |\n  ||||||____||||||____||||||____||||||____|\n  |    ||||||    ||||||    ||||||    ||||||\n5 | {} ||{}|| {} ||{}|| {} ||{}|| {} ||{}||\n  |____||||||____||||||____||||||____||||||\n  ||||||    ||||||    ||||||    ||||||    |\n4 ||{}|| {} ||{}|| {} ||{}|| {} ||{}|| {} |\n  ||||||____||||||____||||||____||||||____|\n  |    ||||||    ||||||    ||||||    ||||||\n3 | {} ||{}|| {} ||{}|| {} ||{}|| {} ||{}||\n  |____||||||____||||||____||||||____||||||\n  ||||||    ||||||    ||||||    ||||||    |\n2 ||{}|| {} ||{}|| {} ||{}|| {} ||{}|| {} |\n  ||||||____||||||____||||||____||||||____|\n  |    ||||||    ||||||    ||||||    ||||||\n1 | {} ||{}|| {} ||{}|| {} ||{}|| {} ||{}||\n  |____||||||____||||||____||||||____||||||\n"""\nWHITE_SQUARE = \'||\'\nBLACK_SQUARE = \'  \'\n\ndef print_chessboard(board):\n    squares = []\n    is_white_square = True\n    for y in \'87654321\':\n        for x in \'abcdefgh\':\n            if x + y in board.keys():\n                squares.append(board[x + y])\n            else:\n                if is_white_square:\n                    squares.append(WHITE_SQUARE)\n                else:\n                    squares.append(BLACK_SQUARE)\n            is_white_square = not is_white_square\n        is_white_square = not is_white_square\n\n    print(BOARD_TEMPLATE.format(*squares))\n\nboard = {\'h1\': \'bK\', \'c6\': \'wQ\', \'g2\': \'bB\', \'h5\': \'bQ\', \'e3\': \'wK\'}\nprint_chessboard(board)\nprint(BOARD_TEMPLATE.count(\'{}\'), len(BOARD_TEMPLATE.splitlines()))\nspam = [\'cat\', \'dog\', \'rat\']\nprint(*spam)\ntry:\n    \'{} {} {}\'.format(spam)\nexcept IndexError as e:\n    print(type(e).__name__ + \': \' + str(e))', 'a    b    c    d    e    f    g    h\n   ____ ____ ____ ____ ____ ____ ____ ____\n  ||||||    ||||||    ||||||    ||||||    |\n8 ||||||    ||||||    ||||||    ||||||    |\n  ||||||____||||||____||||||____||||||____|\n  |    ||||||    ||||||    ||||||    ||||||\n7 |    ||||||    ||||||    ||||||    ||||||\n  |____||||||____||||||____||||||____||||||\n  ||||||    ||||||    ||||||    ||||||    |\n6 ||||||    ||wQ||    ||||||    ||||||    |\n  ||||||____||||||____||||||____||||||____|\n  |    ||||||    ||||||    ||||||    ||||||\n5 |    ||||||    ||||||    ||||||    ||bQ||\n  |____||||||____||||||____||||||____||||||\n  ||||||    ||||||    ||||||    ||||||    |\n4 ||||||    ||||||    ||||||    ||||||    |\n  ||||||____||||||____||||||____||||||____|\n  |    ||||||    ||||||    ||||||    ||||||\n3 |    ||||||    |||||| wK ||||||    ||||||\n  |____||||||____||||||____||||||____||||||\n  ||||||    ||||||    ||||||    ||||||    |\n2 ||||||    ||||||    ||||||    ||bB||    |\n  ||||||____||||||____||||||____||||||____|\n  |    ||||||    ||||||    ||||||    ||||||\n1 |    ||||||    ||||||    ||||||    ||bK||\n  |____||||||____||||||____||||||____||||||\n\n64 27\ncat dog rat\nIndexError: Replacement index 1 out of range for positional args tuple'],
 ['the chessboard commands: move, remove, set, reset, clear, fill and their unchecked errors', "import copy\nSTARTING_PIECES = {'a8': 'bR', 'b8': 'bN', 'c8': 'bB', 'd8': 'bQ',\n'e8': 'bK', 'f8': 'bB', 'g8': 'bN', 'h8': 'bR', 'a7': 'bP', 'b7': 'bP',\n'c7': 'bP', 'd7': 'bP', 'e7': 'bP', 'f7': 'bP', 'g7': 'bP', 'h7': 'bP',\n'a1': 'wR', 'b1': 'wN', 'c1': 'wB', 'd1': 'wQ', 'e1': 'wK', 'f1': 'wB',\n'g1': 'wN', 'h1': 'wR', 'a2': 'wP', 'b2': 'wP', 'c2': 'wP', 'd2': 'wP',\n'e2': 'wP', 'f2': 'wP', 'g2': 'wP', 'h2': 'wP'}\nprint(len(STARTING_PIECES), sum(v[0] == 'w' for v in STARTING_PIECES.values()), sum(v[0] == 'b' for v in STARTING_PIECES.values()))\n\ndef run(main_board, line):\n    response = line.split()\n    if response[0] == 'move':\n        main_board[response[2]] = main_board[response[1]]\n        del main_board[response[1]]\n    elif response[0] == 'remove':\n        del main_board[response[1]]\n    elif response[0] == 'set':\n        main_board[response[1]] = response[2]\n    elif response[0] == 'reset':\n        main_board = copy.copy(STARTING_PIECES)\n    elif response[0] == 'clear':\n        main_board = {}\n    elif response[0] == 'fill':\n        for y in '87654321':\n            for x in 'abcdefgh':\n                main_board[x + y] = response[1]\n    return main_board\n\nb = copy.copy(STARTING_PIECES)\nb = run(b, 'move e2 e4')\nprint('e2' in b, b['e4'], len(b))\nb = run(b, 'remove e7')\nb = run(b, 'set e7 wP')\nprint(b['e7'], len(b))\nb = run(b, 'clear')\nprint(b)\nb = run(b, 'fill wP')\nprint(len(b), set(b.values()))\nb = run(b, 'reset')\nprint(b == STARTING_PIECES, b is STARTING_PIECES)\nfor bad in ('move e3 e4', 'remove e3', 'move e2'):\n    try:\n        run(copy.copy(STARTING_PIECES), bad)\n    except (KeyError, IndexError) as e:\n        print(bad, '->', type(e).__name__ + ': ' + str(e))\nb = run(copy.copy(STARTING_PIECES), 'move e2 e7')\nprint(b['e7'], len(b))", "32 16 16\nFalse wP 32\nwP 32\n{}\n64 {'wP'}\nTrue False\nmove e3 e4 -> KeyError: 'e3'\nremove e3 -> KeyError: 'e3'\nmove e2 -> IndexError: list index out of range\nwP 31"],
 ['guestpicnic.py of the chapter', "all_guests = {'Alice': {'apples': 5, 'pretzels': 12},\n              'Bob': {'ham sandwiches': 3, 'apples': 2},\n              'Carol': {'cups': 3, 'apple pies': 1}}\n\ndef total_brought(guests, item):\n    num_brought = 0\n    for k, v in guests.items():\n        num_brought = num_brought + v.get(item, 0)\n    return num_brought\n\nprint('Number of things being brought:')\nprint(' - Apples         ' + str(total_brought(all_guests, 'apples')))\nprint(' - Cups           ' + str(total_brought(all_guests, 'cups')))\nprint(' - Cakes          ' + str(total_brought(all_guests, 'cakes')))\nprint(' - Ham Sandwiches ' + str(total_brought(all_guests, 'ham sandwiches')))\nprint(' - Apple Pies     ' + str(total_brought(all_guests, 'apple pies')))\nprint(all_guests['Alice']['apples'], all_guests['Bob'].get('cups', 0))", 'Number of things being brought:\n - Apples         7\n - Cups           3\n - Cakes          0\n - Ham Sandwiches 3\n - Apple Pies     1\n5 0'],
 ['pretty-printing answers question 8, and pp keeps insertion order', 'import pprint\ndata = {\'name\': \'Zophie\', \'age\': 8, \'toys\': [\'ball\', \'string\', \'mouse\'], \'owner\': {\'name\': \'Al\', \'city\': \'San Francisco\'}}\npprint.pprint(data, width=40)\npprint.pp(data, width=40)\nprint(pprint.pformat({\'b\': 1, \'a\': 2}), pprint.pformat({\'b\': 1, \'a\': 2}, sort_dicts=False))\nprint(repr(pprint.pformat({\'b\': 1, \'a\': 2}, sort_dicts=True)) == repr("{\'a\': 2, \'b\': 1}"))\nimport json\nprint(json.dumps({\'name\': \'Zophie\', \'toys\': [\'ball\'], \'age\': 8}, sort_keys=True))\nprint(json.loads(\'{"a": [1, 2], "b": null}\'))\ntry:\n    json.dumps({(1, 2): \'x\'})\nexcept TypeError as e:\n    print(type(e).__name__ + \': \' + str(e))', '{\'age\': 8,\n \'name\': \'Zophie\',\n \'owner\': {\'city\': \'San Francisco\',\n           \'name\': \'Al\'},\n \'toys\': [\'ball\', \'string\', \'mouse\']}\n{\'name\': \'Zophie\',\n \'age\': 8,\n \'toys\': [\'ball\', \'string\', \'mouse\'],\n \'owner\': {\'name\': \'Al\',\n           \'city\': \'San Francisco\'}}\n{\'a\': 2, \'b\': 1} {\'b\': 1, \'a\': 2}\nTrue\n{"age": 8, "name": "Zophie", "toys": ["ball"]}\n{\'a\': [1, 2], \'b\': None}\nTypeError: keys must be str, int, float, bool or None, not tuple'],
 ['modelling with a TypedDict, a dataclass and a read-only view', "from typing import TypedDict\nfrom dataclasses import dataclass\nfrom types import MappingProxyType\nclass Piece(TypedDict):\n    color: str\n    kind: str\np = Piece(color='w', kind='K')\nprint(p, type(p).__name__, p == {'color': 'w', 'kind': 'K'})\nprint(Piece.__annotations__)\n@dataclass\nclass Square:\n    file: str\n    rank: int\ns = Square('e', 4)\nprint(s, s.file + str(s.rank))\nview = MappingProxyType({'a': 1})\nprint(view['a'], hasattr(view, '__setitem__'))\ntry:\n    view['a'] = 2\nexcept TypeError as e:\n    print(type(e).__name__ + ': ' + str(e))", "{'color': 'w', 'kind': 'K'} dict True\n{'color': <class 'str'>, 'kind': <class 'str'>}\nSquare(file='e', rank=4) e4\n1 False\nTypeError: 'mappingproxy' object does not support item assignment"],
 ['a match statement can take a dictionary apart by its keys', "def handle(cmd):\n    match cmd:\n        case {'op': 'move', 'from': a, 'to': b}:\n            return 'move ' + a + ' to ' + b\n        case {'op': 'remove', 'at': a}:\n            return 'remove ' + a\n        case {'op': str(o), **rest}:\n            return 'unknown ' + o + ' with ' + str(sorted(rest))\n        case _:\n            return 'not a command'\nprint(handle({'op': 'move', 'from': 'e2', 'to': 'e4', 'extra': 1}))\nprint(handle({'op': 'remove', 'at': 'e7'}))\nprint(handle({'op': 'fill', 'piece': 'wP'}))\nprint(handle(['move']))", "move e2 to e4\nremove e7\nunknown fill with ['piece']\nnot a command"],
 ['ordered dictionary: equality that cares about order', "from collections import OrderedDict\na = OrderedDict([('a', 1), ('b', 2)])\nb = OrderedDict([('b', 2), ('a', 1)])\nprint(a == b, dict(a) == dict(b), a == dict(b))\na.move_to_end('a')\nprint(list(a))\nfrom collections import ChainMap\ndefaults = {'color': 'red', 'user': 'guest'}\noverrides = {'user': 'admin'}\ncm = ChainMap(overrides, defaults)\nprint(cm['user'], cm['color'], dict(cm))", "False True True\n['b', 'a']\nadmin red {'color': 'red', 'user': 'admin'}"],
 ['practice questions 1 to 8 answered by running the code', "import pprint\nprint({})\nprint({'foo': 42})\ntry:\n    {'bar': 100}['foo']\nexcept KeyError as e:\n    print(type(e).__name__ + ': ' + str(e))\nspam = {'cat': 'meow'}\nprint('cat' in spam, 'cat' in spam.keys(), 'cat' in spam.values(), 'meow' in spam.values())\nspam = {}\nif 'color' not in spam:\n    spam['color'] = 'black'\nalt = {}\nalt.setdefault('color', 'black')\nprint(spam == alt)\nprint(pprint.pformat({'b': 2, 'a': 1}))", "{}\n{'foo': 42}\nKeyError: 'foo'\nTrue True False True\nTrue\n{'a': 1, 'b': 2}"],
 ["isValidChessBoard: a validator for the chapter's own notation", "def is_valid_chess_board(board):\n    files, ranks = 'abcdefgh', '12345678'\n    kinds = 'PNBRQK'\n    count = {'w': 0, 'b': 0}\n    pawns = {'w': 0, 'b': 0}\n    kings = {'w': 0, 'b': 0}\n    for square, piece in board.items():\n        if len(square) != 2 or square[0] not in files or square[1] not in ranks:\n            return False\n        if len(piece) != 2 or piece[0] not in 'wb' or piece[1] not in kinds:\n            return False\n        count[piece[0]] += 1\n        if piece[1] == 'P':\n            pawns[piece[0]] += 1\n        if piece[1] == 'K':\n            kings[piece[0]] += 1\n    return all(kings[c] == 1 and count[c] <= 16 and pawns[c] <= 8 for c in 'wb')\nstart = {f + '1': 'w' + p for f, p in zip('abcdefgh', 'RNBQKBNR')}\nstart.update({f + '2': 'wP' for f in 'abcdefgh'})\nstart.update({f + '8': 'b' + p for f, p in zip('abcdefgh', 'RNBQKBNR')})\nstart.update({f + '7': 'bP' for f in 'abcdefgh'})\nprint(len(start), is_valid_chess_board(start))\nprint(is_valid_chess_board({'h1': 'bK', 'c6': 'wQ', 'g2': 'bB', 'h5': 'bQ', 'e3': 'wK'}))\nprint(is_valid_chess_board({'h1': 'bK', 'e3': 'wK', 'z9': 'wP'}))\nprint(is_valid_chess_board({'h1': 'bK', 'c6': 'wQ'}))\nprint(is_valid_chess_board({'h1': 'bK', 'e3': 'wK', 'a1': 'wX'}))\npawns = {x + '2': 'wP' for x in 'abcdefgh'}\npawns['a3'] = 'wP'\npawns.update({'h1': 'bK', 'e1': 'wK'})\nprint(is_valid_chess_board(pawns))\nprint(is_valid_chess_board({}))", '32 True\nTrue\nFalse\nFalse\nFalse\nFalse\nFalse'],
 ['display_inventory and add_to_inventory of the practice programs', "def display_inventory(inventory):\n    print('Inventory:')\n    item_total = 0\n    for k, v in inventory.items():\n        print(str(v) + ' ' + k)\n        item_total += v\n    print('Total number of items: ' + str(item_total))\n\ndef add_to_inventory(inventory, added_items):\n    for item in added_items:\n        inventory[item] = inventory.get(item, 0) + 1\n    return inventory\n\nstuff = {'rope': 1, 'torch': 6, 'gold coin': 42, 'dagger': 1, 'arrow': 12}\ndisplay_inventory(stuff)\ninv = {'gold coin': 42, 'rope': 1}\ndragon_loot = ['gold coin', 'dagger', 'gold coin', 'gold coin', 'ruby']\ninv = add_to_inventory(inv, dragon_loot)\ndisplay_inventory(inv)\nprint(sorted(inv.items(), key=lambda p: -p[1]))", "Inventory:\n1 rope\n6 torch\n42 gold coin\n1 dagger\n12 arrow\nTotal number of items: 62\nInventory:\n45 gold coin\n1 rope\n1 dagger\n1 ruby\nTotal number of items: 48\n[('gold coin', 45), ('rope', 1), ('dagger', 1), ('ruby', 1)]"],
